    ('5','5.2','Banking','["5.2.1 Banking services", "the different types of banking services: - accounts: current and deposit/savings - customer services: ATM, night safe, foreign currency, financial advice and telephone banking - payments: cash, cheque, credit card, debit card, store card, credit transfer, standing order, direct debit, electronic transfer and documentary credit (letter of credit) - sources of finance: loan, overdraft, mortgage and hire purchase", "the appropriateness of choosing banking services in given situations 5.2.2 Digital technology in banking", "the different types of digital banking: internet banking and mobile banking", "the advantages and disadvantages of digital banking", "the impact of digital banking: closure of bank branches, more digital-only banks and less use of cash (cashless society)"]'::jsonb,1),
    ('5','5.3','Insurance','["5.3.1 Purposes of insurance", "the purposes of insurance: risk reduction, compensation, financial protection, business confidence and investment 5.3.2 Types of insurance risk", "the different types of insurance risk: consequential loss, employer''s liability, fire, motor, premises, public liability and theft 5.3.3 How enterprises make use of insurance", "the use of pooling of insurance risk", "the calculation of insurance premiums", "the use of insurance documents: proposal form, cover note and policy", "the role of an insurance broker"]'::jsonb,2),
    ('5','5.4','Sources of finance and commercial performance','["5.4.1 Ways in which entrepreneurs and commercial enterprises raise finance", "the meaning of entrepreneurship", "the sources of short-term finance: trade credit, debt factoring, hire purchase, leasing, sale and leaseback, overdraft, selling assets, owner''s savings and retained profit", "the sources of long-term finance: ordinary and preference shares, loans, debentures, venture capital and crowdfunding", "the advantages and disadvantages of each source of finance", "the appropriateness of choice of source of finance in given situations", "the meaning and use of financial terms: sales, revenue, profit, working capital, assets and liabilities, interest, capital, cash discounts and trade discounts", "5.4.2 Commercial calculations", "the calculation of revenue, gross profit, gross profit margin, profit for the year (net profit), working capital and mark-up percentage = Selling price per unit × Number of units sold 1 Revenue (Sales or Turnover) 2 Gross profit = Revenue - Cost of Sales (the cost of purchasing inventory) = Gross profit ÷ Revenue × 100 3 Gross profit margin (%) 4 Net profit/net loss for the year = Gross profit - Expenses 5 Working capital Current assets - Current liabilities = (Average Selling Price - Unit Cost) ÷ Unit Cost 6 Mark-up percentage 5.4.3 Improving commercial performance", "the methods to improve sales turnover, profit, mark-up and working capital, e.g. reducing expenses, increasing mark-up, changing prices, improving advertising, introducing new products in given situations"]'::jsonb,3),
    ('6','6.1','Sustainability','["6.1.1 Purpose of sustainability in the supply chain", "the purpose of sustainability in the supply chain: making commercial processes eco-friendly and environmentally responsible for future generations 6.1.2 Actions to improve sustainability", "actions to improve sustainability: using sustainable materials in the production process, implementing sustainable logistics, reducing packaging, selling eco-friendly products, recycling and reducing waste, reducing the need for returns and exchanges, offering digital resale marketplaces, offering free repair services and water stewardship"]'::jsonb,0),
    ('6','6.2','Ethics','["6.2.1 Ethics and ethical issues in commerce", "the meaning of ethics", "the role of fair trade in commerce", "ethical issues in commerce: misleading advertising and harmful disposal of products"]'::jsonb,1),
    ('6','6.3','Consumer protection','["the reasons for consumer protection", "the actions taken by buyers and sellers to resolve consumer protection complaints"]'::jsonb,2)
  ) AS x(tcode, scode, sname, objectives, sort)
  JOIN public.syllabus_topics t ON t.template_id=v_tpl AND t.code=x.tcode AND t.deleted_at IS NULL;
  RAISE NOTICE 'Loaded Commerce O Level (O2)';
END $$;
